<script setup lang="ts">
import{onMounted,ref}from'vue';import{approvePurchase,createPurchase,getPurchases,getSuppliers,getVariants,getWarehouses,receivePurchase,submitPurchase,type PurchaseOrder,type Supplier,type Variant,type Warehouse}from'@/services/business';import{useAuthStore}from'@/stores/auth'
const auth=useAuthStore(),items=ref<PurchaseOrder[]>([]),suppliers=ref<Supplier[]>([]),warehouses=ref<Warehouse[]>([]),variants=ref<Variant[]>([]),status=ref(''),loading=ref(false),error=ref(''),supplierId=ref(''),warehouseId=ref(''),variantId=ref(''),quantity=ref(1),unitCost=ref(0)
async function load(){loading.value=true;try{[items.value,suppliers.value,warehouses.value,variants.value]=await Promise.all([getPurchases(status.value),getSuppliers(),getWarehouses(),getVariants()])}catch{error.value='Không thể tải dữ liệu nhập hàng.'}finally{loading.value=false}}
async function action(id:string,type:'submit'|'approve'){error.value='';try{type==='submit'?await submitPurchase(id):await approvePurchase(id);await load()}catch{error.value='Không thể chuyển trạng thái đơn nhập hàng.'}}
async function create(){try{await createPurchase({supplierId:supplierId.value,warehouseId:warehouseId.value,currency:'VND',items:[{variantId:variantId.value,quantity:quantity.value,unitCost:unitCost.value}]});await load()}catch{error.value='Không thể tạo đơn nhập hàng.'}}
async function receive(p:PurchaseOrder){const pending=p.items.filter(i=>Number(i.receivedQuantity)<Number(i.orderedQuantity)).map(i=>({purchaseOrderItemId:i.id,quantity:Number(i.orderedQuantity)-Number(i.receivedQuantity)}));if(!pending.length)return;try{await receivePurchase(p.id,{idempotencyKey:crypto.randomUUID(),note:'Receive remaining quantity from purchasing screen',items:pending});await load()}catch{error.value='Không thể nhận hàng. Chỉ các PO đã duyệt/đang nhận mới hợp lệ.'}}
onMounted(load)
</script>
<template><section class="p-6 lg:p-8"><div class="flex flex-wrap justify-between gap-4"><div><p class="text-sm font-semibold text-cyan-700">Nhập hàng</p><h2 class="text-3xl font-bold">Đơn nhập hàng</h2></div><select v-model="status" class="rounded-lg border px-3" @change="load"><option value="">Tất cả</option><option value="DRAFT">Bản nháp</option><option value="PENDING_APPROVAL">Chờ duyệt</option><option value="APPROVED">Đã duyệt</option><option value="RECEIVING">Đang nhận hàng</option><option value="COMPLETED">Hoàn tất</option></select></div><form v-if="auth.hasPermission('purchase.create')" class="mt-6 grid gap-3 rounded-xl border bg-white p-5 md:grid-cols-5" @submit.prevent="create"><select v-model="supplierId" required class="rounded border p-3"><option value="">Nhà cung cấp</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-model="warehouseId" required class="rounded border p-3"><option value="">Kho nhận</option><option v-for="w in warehouses" :key="w.id" :value="w.id">{{w.name}}</option></select><select v-model="variantId" required class="rounded border p-3"><option value="">SKU</option><option v-for="v in variants" :key="v.id" :value="v.id">{{v.sku}}</option></select><input v-model.number="quantity" type="number" min="0.0001" step="0.0001" class="rounded border p-3" placeholder="Số lượng"><input v-model.number="unitCost" type="number" min="0" step="0.0001" class="rounded border p-3" placeholder="Giá nhập"><button class="rounded bg-cyan-700 p-3 text-white md:col-span-5">Tạo PO</button></form><p v-if="error" class="mt-5 rounded-lg bg-red-50 p-4 text-red-800">{{error}}</p><div v-if="!loading" class="mt-6 overflow-x-auto rounded-xl border bg-white"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Mã PO</th><th class="p-4">Nhà cung cấp</th><th class="p-4">Kho</th><th class="p-4">Tổng</th><th class="p-4">Trạng thái</th><th class="p-4">Thao tác</th></tr></thead><tbody class="divide-y"><tr v-for="p in items" :key="p.id"><td class="p-4 font-mono">{{p.poNumber}}</td><td class="p-4">{{p.supplierName}}</td><td class="p-4">{{p.warehouseName}}</td><td class="p-4">{{Number(p.total).toLocaleString()}} {{p.currency}}</td><td class="p-4"><StatusBadge :value="p.status" /></td><td class="p-4"><button v-if="p.status==='DRAFT'&&auth.hasPermission('purchase.create')" class="text-cyan-700" @click="action(p.id,'submit')">Gửi duyệt</button><button v-if="p.status==='PENDING_APPROVAL'&&auth.hasPermission('purchase.approve')" class="text-cyan-700" @click="action(p.id,'approve')">Phê duyệt</button><button v-if="['APPROVED','RECEIVING'].includes(p.status)&&auth.hasPermission('purchase.receive')" class="text-cyan-700" @click="receive(p)">Nhận phần còn lại</button></td></tr></tbody></table></div></section></template>
